 document.addEventListener('click',e=>{const button=e.target.closest('[data-item-calendar]');if(!button)return;calendarItem=button.dataset.itemCalendar;const f=document.getElementById('rcQuickOrder');calendarDraft=[...(itemDates[calendarItem]||quotation(f).rows.find(r=>String(r.id)===calendarItem)?.dates||[])];calendarMonth=new Date((calendarDraft.slice().sort()[0]||iso(new Date()))+'T00:00:00');calendarMonth.setDate(1);drawCalendar();calendar.showModal()});
 calendar.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-calendar-close')){calendar.close();return}if(b.dataset.calendarMonth){calendarMonth.setMonth(calendarMonth.getMonth()+Number(b.dataset.calendarMonth));drawCalendar();return}if(b.dataset.calendarDay){const d=b.dataset.calendarDay;calendarDraft=calendarDraft.includes(d)?calendarDraft.filter(x=>x!==d):[...calendarDraft,d];drawCalendar();return}if(b.hasAttribute('data-calendar-default')||b.hasAttribute('data-calendar-save')){if(b.hasAttribute('data-calendar-default'))delete itemDates[calendarItem];else itemDates[calendarItem]=calendarDraft.slice().sort();sessionStorage.setItem('rentcam_item_dates',JSON.stringify(itemDates));calendar.close();estimate()}});
